{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "overview_section",
        "film_recommendations_section",
        "movie_lineup_section",
        "snack_recipes_section",
        "trivia_section",
        "vibe_checklist_section",
        "quick_actions_section",
        "sources_section"
      ]
    },
    "overview_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "overview_header_stack",
        "hero_image",
        "overview_description"
      ]
    },
    "overview_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "overview_title",
        "overview_icon"
      ]
    },
    "overview_title": {
      "type": "Text",
      "props": {
        "text": "Seattle Cyberpunk Marathon Overview",
        "variant": "h1"
      },
      "children": []
    },
    "overview_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/moon-stars.svg"
      },
      "children": []
    },
    "hero_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Seattle_Skyline_at_Night.jpg/1200px-Seattle_Skyline_at_Night.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "overview_description": {
      "type": "Text",
      "props": {
        "text": "Seattle's nocturnal cityscape provides the perfect backdrop for a neon-dystopia marathon on November 16. This plan focuses on the definitive aesthetic of 1980s cyberpunk cinema."
      },
      "children": []
    },
    "film_recommendations_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "film_recommendations_title",
        "film_table"
      ]
    },
    "film_recommendations_title": {
      "type": "Text",
      "props": {
        "text": "Cyberpunk Film Recommendations",
        "variant": "h2"
      },
      "children": []
    },
    "film_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "Movie",
            "label": "Movie"
          },
          {
            "key": "Year",
            "label": "Year"
          },
          {
            "key": "Director",
            "label": "Director"
          },
          {
            "key": "Style",
            "label": "Style"
          }
        ],
        "rows": [
          {
            "Movie": "Blade Runner",
            "Year": "1982",
            "Director": "Ridley Scott",
            "Style": "Tech-Noir"
          },
          {
            "Movie": "Akira",
            "Year": "1988",
            "Director": "Katsuhiro Otomo",
            "Style": "Biopunk"
          },
          {
            "Movie": "RoboCop",
            "Year": "1987",
            "Director": "Paul Verhoeven",
            "Style": "Satirical Dystopia"
          }
        ],
        "domain": "playlist",
        "preferredPresentation": "cards",
        "primaryColumn": "Movie",
        "highlightColumns": [
          "Year",
          "Director"
        ]
      },
      "children": []
    },
    "movie_lineup_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "movie_lineup_header_stack",
        "movie_lineup_list"
      ]
    },
    "movie_lineup_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "movie_lineup_title",
        "movie_lineup_icon"
      ]
    },
    "movie_lineup_title": {
      "type": "Text",
      "props": {
        "text": "Movie Lineup",
        "variant": "h2"
      },
      "children": []
    },
    "movie_lineup_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/ticket-perforated.svg"
      },
      "children": []
    },
    "movie_lineup_list": {
      "type": "List",
      "props": {},
      "children": [
        "blade_runner_card",
        "akira_card",
        "robocop_card"
      ]
    },
    "blade_runner_card": {
      "type": "Card",
      "props": {},
      "children": [
        "blade_runner_text"
      ]
    },
    "blade_runner_text": {
      "type": "Text",
      "props": {
        "text": "Blade Runner: A detective hunts down bioengineered humanoids in a rain-soaked, neon-lit Los Angeles."
      },
      "children": []
    },
    "akira_card": {
      "type": "Card",
      "props": {},
      "children": [
        "akira_text"
      ]
    },
    "akira_text": {
      "type": "Text",
      "props": {
        "text": "Akira: A biker gang member gains psychic powers in a post-apocalyptic Neo-Tokyo, threatening the world."
      },
      "children": []
    },
    "robocop_card": {
      "type": "Card",
      "props": {},
      "children": [
        "robocop_text"
      ]
    },
    "robocop_text": {
      "type": "Text",
      "props": {
        "text": "RoboCop: A mortally wounded cop is transformed into a powerful cyborg to fight crime in a decaying Detroit."
      },
      "children": []
    },
    "snack_recipes_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "snack_recipes_header_stack",
        "snack_recipes_list"
      ]
    },
    "snack_recipes_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "snack_recipes_title",
        "snack_recipes_icon"
      ]
    },
    "snack_recipes_title": {
      "type": "Text",
      "props": {
        "text": "Neon-Dystopia Snack Recipes",
        "variant": "h2"
      },
      "children": []
    },
    "snack_recipes_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/cup-hot.svg"
      },
      "children": []
    },
    "snack_recipes_list": {
      "type": "List",
      "props": {},
      "children": [
        "electric_noodles_card",
        "synth_sliders_card"
      ]
    },
    "electric_noodles_card": {
      "type": "Card",
      "props": {},
      "children": [
        "electric_noodles_text"
      ]
    },
    "electric_noodles_text": {
      "type": "Text",
      "props": {
        "text": "Electric Noodles (Vegan): Glass noodles dyed with purple cabbage juice and lime, topped with neon-green edamame and bright peppers."
      },
      "children": []
    },
    "synth_sliders_card": {
      "type": "Card",
      "props": {},
      "children": [
        "synth_sliders_text"
      ]
    },
    "synth_sliders_text": {
      "type": "Text",
      "props": {
        "text": "Synth-Sliders: Mini beef burgers served on charcoal-black buns with a vibrant blue-cheese spread and spicy \"circuit\" sauce."
      },
      "children": []
    },
    "trivia_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "trivia_title",
        "trivia_list"
      ]
    },
    "trivia_title": {
      "type": "Text",
      "props": {
        "text": "1980s Sci-Fi Production Trivia",
        "variant": "h2"
      },
      "children": []
    },
    "trivia_list": {
      "type": "List",
      "props": {},
      "children": [
        "trivia_blade_runner",
        "trivia_akira",
        "trivia_robocop",
        "trivia_tron",
        "trivia_effects"
      ]
    },
    "trivia_blade_runner": {
      "type": "Text",
      "props": {
        "text": "Blade Runner: The iconic \"Tears in Rain\" monologue was largely improvised by actor Rutger Hauer on the night of filming."
      },
      "children": []
    },
    "trivia_akira": {
      "type": "Text",
      "props": {
        "text": "Akira: The film utilized over 160,000 hand-drawn animation cells and a record-breaking 327 colors."
      },
      "children": []
    },
    "trivia_robocop": {
      "type": "Text",
      "props": {
        "text": "RoboCop: The suit was so heavy and hot that Peter Weller lost several pounds a day in water weight."
      },
      "children": []
    },
    "trivia_tron": {
      "type": "Text",
      "props": {
        "text": "Tron: It was the first film to use extensive 3D computer animation, though it was disqualified from Oscar consideration for \"cheating.\""
      },
      "children": []
    },
    "trivia_effects": {
      "type": "Text",
      "props": {
        "text": "Special Effects: Most 80s sci-fi relied on physical miniatures and matte paintings before the digital revolution of the 90s."
      },
      "children": []
    },
    "vibe_checklist_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "vibe_checklist_title",
        "vibe_checklist_list"
      ]
    },
    "vibe_checklist_title": {
      "type": "Text",
      "props": {
        "text": "Vibe Checklist: Decor and Attire",
        "variant": "h2"
      },
      "children": []
    },
    "vibe_checklist_list": {
      "type": "List",
      "props": {},
      "children": [
        "decor_text",
        "attire_text"
      ]
    },
    "decor_text": {
      "type": "Text",
      "props": {
        "text": "Decor: Blue and pink LED neon strips, blacklight posters, and synthetic fog machine."
      },
      "children": []
    },
    "attire_text": {
      "type": "Text",
      "props": {
        "text": "Attire: Transparent raincoats, mirrored aviators, metallic fabrics, and oversized leather jackets."
      },
      "children": []
    },
    "quick_actions_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "quick_actions_title",
        "quick_actions_stack"
      ]
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap"
      },
      "children": [
        "play_soundtrack_button",
        "seattle_weather_button"
      ]
    },
    "play_soundtrack_button": {
      "type": "Button",
      "props": {
        "label": "Play Soundtrack"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://open.spotify.com"
          }
        }
      },
      "children": []
    },
    "seattle_weather_button": {
      "type": "Button",
      "props": {
        "label": "Seattle Weather"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.weather.gov"
          }
        }
      },
      "children": []
    },
    "sources_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "sources_title",
        "sources_stack"
      ]
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "imdb_button",
        "cyberpunk_guide_button"
      ]
    },
    "imdb_button": {
      "type": "Button",
      "props": {
        "label": "IMDb Film Trivia",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.imdb.com"
          }
        }
      },
      "children": []
    },
    "cyberpunk_guide_button": {
      "type": "Button",
      "props": {
        "label": "Cyberpunk Aesthetic Guide",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.cyberpunk.net"
          }
        }
      },
      "children": []
    }
  }
}
